import React from "react";
import clsx from "clsx";
import { Popover as PopoverStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import Popper, { type PopperProps } from "../Popper";

export type PopoverProps = PopperProps & {
  /**
   * popover elevation (shadow size)
   * - use 1 for dropdown like components
   * - use 3 for menu like components
   * - use 6 for content requesting more attention
   * @default 3
   */
  elevation?: 6 | 3 | 1;
};

const useStyles = createUseStyles(PopoverStyles, "popover");

export const Popover = (props: PopoverProps, ref: React.Ref<HTMLDivElement>) => {
  const { arrowClassName, className, children, elevation = 3, ...rest } = props;
  const classes = useStyles();

  let elevationClass = undefined;
  if (elevation === 1) elevationClass = classes._low;
  else if (elevation === 6) elevationClass = classes._high;

  return (
    <Popper
      className={clsx(className, classes.root, elevationClass)}
      arrowClassName={clsx(classes.arrow, arrowClassName)}
      {...rest}
    >
      <div ref={ref}>{children}</div>
    </Popper>
  );
};

export default React.forwardRef<HTMLDivElement, PopoverProps>(Popover);
